```java
@Test
void sshArgumentsFollowTheStructuredTargetAndTheHostKeyPolicy() {
    var runner = new RecordingRunner(false);
    var aliasOnly = new RemoteHostInstaller(runner, new SshCommandLine(
            Optional.of(java.nio.file.Path.of("/data/ssh-known-hosts"))));

    SshTarget alias = SshTarget.ofHost("deploy-alias");
    List<String> aliasArgs = aliasOnly.openTunnel(alias, new RemoteHostInstaller.RemotePorts(1, 2)).command();
    assertTrue(aliasArgs.contains("deploy-alias"));
    assertFalse(aliasArgs.contains("user@deploy-alias"));
    assertFalse(aliasArgs.contains("-p"));
    assertFalse(aliasArgs.contains("-i"));
    assertTrue(aliasArgs.contains("UserKnownHostsFile=/data/ssh-known-hosts"));
    assertTrue(aliasArgs.contains("StrictHostKeyChecking=yes"));
    assertTrue(aliasArgs.contains("BatchMode=yes"));

    SshTarget explicit = new SshTarget("deploy", "10.0.0.9", OptionalInt.of(2222),
            Optional.of(java.nio.file.Path.of("C:/keys/id_ed25519")));
    List<String> explicitArgs = aliasOnly.openTunnel(explicit, new RemoteHostInstaller.RemotePorts(1, 2)).command();
    assertTrue(explicitArgs.contains("deploy@10.0.0.9"));
    assertEquals(2222, Integer.parseInt(explicitArgs.get(explicitArgs.indexOf("-p") + 1)));
    assertTrue(explicitArgs.contains("-i"));
    assertFalse(explicitArgs.contains("IdentitiesOnly"));

    SshCommandLine plain = new SshCommandLine(Optional.empty());
    List<String> plainArgs = plain.scp(alias, java.nio.file.Path.of("/tmp/bundle.tgz"), "/remote/x");
    assertFalse(plainArgs.contains("-P"));
    assertFalse(plainArgs.contains("StrictHostKeyChecking=yes"));
}
```

Also `assertTrue(explicitArgs.contains("-i"))` — the identity path is normalized; on Windows `/data/...` → `C:\data\...`? `Path.of("C:/keys/id_ed25519").toAbsolutePath().normalize().toString()` on Windows → `C:\keys\id_ed25519`. The test asserting `contains("-i")` is enough.

